# 第三部分：执行逻辑

def count_herbs(data_sections):
    """统计药材总数"""
    total = 0
    for section in data_sections:
        total += len(section)
    return total

def expand(verbose=True):
    """主执行函数"""
    conn = sqlite3.connect(str(DB_PATH))
    cur = conn.cursor()

    # 导入药材
    all_herbs = (
        HERBS_JIEBIAO + HERBS_QINGRE + HERBS_XIEXIA + HERBS_QUFENGSHI +
        HERBS_HUASHI + HERBS_LISHUI + HERBS_WENLI + HERBS_LIQI +
        HERBS_XIAOSHI + HERBS_QUCHONG + HERBS_ZHIXUE + HERBS_HUOXUE +
        HERBS_HUATAN + HERBS_ANSHEN + HERBS_PINGGAN + HERBS_KAIQIAO +
        HERBS_BUQI + HERBS_BUYANG + HERBS_BUXUE + HERBS_BUYIN +
        HERBS_SHOUSE + HERBS_YONGTU + HERBS_GONGDU + HERBS_BADU +
        HERBS_MINZU + HERBS_MJIAN + HERBS_SHILIAO + HERBS_KUANGWU +
        HERBS_DONGWU + HERBS_TESE + HERBS_HAIYANG + HERBS_OTHER
    )
    total_herbs = len(all_herbs)

    # 获取现有药材名
    existing_herbs = {r[0] for r in cur.execute("SELECT name FROM herbs")}
    herb_added = 0
    for h in all_herbs:
        name, category, nature, flavor, meridian, efficacy, indications, usage, contraindications = h
        if name in existing_herbs:
            continue
        cur.execute(
            "INSERT INTO herbs (name, category, nature, flavor, meridian, efficacy, indications, usage, contraindications, source) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (name, category, nature, flavor, meridian, efficacy, indications, usage, contraindications, "系统扩充"),
        )
        existing_herbs.add(name)
        herb_added += 1

    new_herb_total = cur.execute("SELECT COUNT(*) FROM herbs").fetchone()[0]
    conn.commit()

    if verbose:
        print(f"药材: 提供 {total_herbs} 种, 新增 {herb_added} 种, 总计 {new_herb_total} 种")

    # 导入方剂
    existing_formulas = {r[0] for r in cur.execute("SELECT name FROM formulas")}
    formula_added = 0
    total_formulas_provided = len(FORMULAS_NEW)
    for f in FORMULAS_NEW:
        name, category, source_book, composition, functions, indications, usage, modification = f
        if name in existing_formulas:
            continue
        cur.execute(
            "INSERT INTO formulas (name, category, source_book, composition, functions, indications, usage, modification, source) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (name, category, source_book, composition, functions, indications, usage, modification, "系统扩充"),
        )
        existing_formulas.add(name)
        formula_added += 1

    new_formula_total = cur.execute("SELECT COUNT(*) FROM formulas").fetchone()[0]
    conn.commit()

    if verbose:
        print(f"方剂: 提供 {total_formulas_provided} 首, 新增 {formula_added} 首, 总计 {new_formula_total} 首")

    conn.close()
    return herb_added, formula_added, new_herb_total, new_formula_total

if __name__ == "__main__":
    import time
    start = time.time()
    h_added, f_added, h_total, f_total = expand()
    elapsed = time.time() - start
    print(f"\n✅ 扩充完成! 耗时 {elapsed:.2f}s")
    print(f"   药材: +{h_added} → {h_total}")
    print(f"   方剂: +{f_added} → {f_total}")


